CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT,"email" TEXT UNIQUE,"emailVerified" TIMESTAMP(3),"image" TEXT,"password" TEXT,"role" TEXT NOT NULL DEFAULT 'USER',"remainingMins" DOUBLE PRECISION NOT NULL DEFAULT 120,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Account" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"type" TEXT NOT NULL,"provider" TEXT NOT NULL,"providerAccountId" TEXT NOT NULL,"refresh_token" TEXT,"access_token" TEXT,"expires_at" INTEGER,"token_type" TEXT,"scope" TEXT,"id_token" TEXT,"session_state" TEXT,UNIQUE("provider","providerAccountId"));
CREATE TABLE "Session" ("id" TEXT PRIMARY KEY,"sessionToken" TEXT NOT NULL UNIQUE,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"expires" TIMESTAMP(3) NOT NULL);
CREATE TABLE "VerificationToken" ("id" TEXT PRIMARY KEY,"identifier" TEXT NOT NULL,"token" TEXT NOT NULL UNIQUE,"expires" TIMESTAMP(3) NOT NULL,UNIQUE("identifier","token"));
CREATE TABLE "Project" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"title" TEXT NOT NULL,"originalVideoUrl" TEXT,"status" TEXT NOT NULL DEFAULT 'PENDING',"progress" INTEGER NOT NULL DEFAULT 0,"duration" DOUBLE PRECISION NOT NULL DEFAULT 0,"thumbnailUrl" TEXT,"workflowState" TEXT NOT NULL DEFAULT 'UPLOADED',"sourceProvider" TEXT NOT NULL DEFAULT 'local',"sourceMediaId" TEXT,"originalFilename" TEXT,"mimeType" TEXT,"sourceS3Key" TEXT,"sourceBytes" BIGINT NOT NULL DEFAULT 0,"cloudAvailable" BOOLEAN NOT NULL DEFAULT true,"editedAt" TIMESTAMP(3),"exportedAt" TIMESTAMP(3),"publishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Clip" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"title" TEXT NOT NULL,"startTime" DOUBLE PRECISION NOT NULL,"endTime" DOUBLE PRECISION NOT NULL,"duration" DOUBLE PRECISION NOT NULL,"videoUrl" TEXT,"viralScore" INTEGER NOT NULL DEFAULT 0,"reason" TEXT,"transcript" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Video" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"title" TEXT NOT NULL,"url" TEXT NOT NULL,"s3Key" TEXT,"duration" DOUBLE PRECISION NOT NULL,"size" TEXT,"bytes" BIGINT NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AudioTrack" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"title" TEXT NOT NULL,"url" TEXT NOT NULL,"s3Key" TEXT,"duration" DOUBLE PRECISION NOT NULL,"playStartTime" DOUBLE PRECISION NOT NULL DEFAULT 0,"volume" DOUBLE PRECISION NOT NULL DEFAULT 1,"fadeIn" DOUBLE PRECISION NOT NULL DEFAULT 0,"fadeOut" DOUBLE PRECISION NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Export" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"resolution" TEXT NOT NULL DEFAULT 'P1080',"format" TEXT NOT NULL DEFAULT 'MP4',"status" TEXT NOT NULL DEFAULT 'PENDING',"progress" INTEGER NOT NULL DEFAULT 0,"downloadUrl" TEXT,"s3Key" TEXT,"duration" DOUBLE PRECISION NOT NULL DEFAULT 0,"retryCount" INTEGER NOT NULL DEFAULT 0,"error" TEXT,"bytes" BIGINT NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "ProjectVersion" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"version" INTEGER NOT NULL,"videoClipsJson" TEXT NOT NULL,"audioClipsJson" TEXT NOT NULL,"elementsJson" TEXT NOT NULL DEFAULT '[]',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ActivityLog" ("id" TEXT PRIMARY KEY,"userId" TEXT REFERENCES "User"("id") ON DELETE SET NULL,"action" TEXT NOT NULL,"details" TEXT,"ipAddress" TEXT,"userAgent" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "PublishSettings" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL UNIQUE REFERENCES "User"("id") ON DELETE CASCADE,"makeWebhookUrl" TEXT,"instagramConnected" BOOLEAN NOT NULL DEFAULT false,"instagramAccountName" TEXT,"instagramAccessToken" TEXT,"instagramAccountId" TEXT,"youtubeConnected" BOOLEAN NOT NULL DEFAULT false,"youtubeChannelName" TEXT,"youtubeAccessToken" TEXT,"youtubeRefreshToken" TEXT,"youtubeClientId" TEXT,"youtubeClientSecret" TEXT,"pexelsApiKey" TEXT DEFAULT '',"pixabayApiKey" TEXT DEFAULT '',"geminiApiKey" TEXT DEFAULT '',"aiModel" TEXT DEFAULT 'gemini-2.0-flash',"aiTone" TEXT DEFAULT 'clickbait',"aiInstructions" TEXT DEFAULT '',"subtitleFont" TEXT DEFAULT 'Montserrat',"subtitleColor" TEXT DEFAULT '#FFFF00',"subtitleSize" TEXT DEFAULT 'lg',"subtitleStroke" BOOLEAN NOT NULL DEFAULT true,"subtitleUppercase" BOOLEAN NOT NULL DEFAULT true,"defaultMusicVolume" DOUBLE PRECISION NOT NULL DEFAULT .15,"duckingLevel" DOUBLE PRECISION NOT NULL DEFAULT .8,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "PublishHistory" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL REFERENCES "Project"("id") ON DELETE CASCADE,"clipId" TEXT NOT NULL,"clipTitle" TEXT NOT NULL,"platform" TEXT NOT NULL,"status" TEXT NOT NULL,"scheduledFor" TIMESTAMP(3),"postUrl" TEXT,"error" TEXT,"caption" TEXT,"hashtags" TEXT,"youtubeTitle" TEXT,"youtubeDesc" TEXT,"youtubeTags" TEXT,"thumbnailUrl" TEXT,"mediaPath" TEXT,"platformPostId" TEXT,"idempotencyKey" TEXT NOT NULL UNIQUE,"attemptCount" INTEGER NOT NULL DEFAULT 0,"processingStage" TEXT NOT NULL DEFAULT 'QUEUED',"privacyStatus" TEXT,"publishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "StockMediaUse" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"provider" TEXT NOT NULL,"mediaId" TEXT NOT NULL,"title" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("userId","provider","mediaId"));
CREATE INDEX "StockMediaUse_userId_createdAt_idx" ON "StockMediaUse"("userId","createdAt");
